sys_script.script:
(function executeRule(current, previous) {

    var assignmentId = current.getValue('assignment');

    var analyzer = new LicenseRenewalAnalyzer();

    var result = analyzer.analyzeLicense(assignmentId);

    // Set analysis results
    current.setValue(
        'days_since_last_use',
        result.daysSinceLastUse
    );

    current.setValue(
        'usage_score',
        result.usageScore
    );

    current.setValue(
        'cost_score',
        result.costScore
    );

    current.setValue(
        'renewal_score',
        result.renewalScore
    );

    current.setValue(
        'recommendation',
        result.recommendation
    );

    current.setValue(
        'potential_saving',
        result.potentialSaving
    );


    // Calculate Days to Expiry
    var license = new GlideRecord(
        'x_1904737_smart_0_software_license'
    );

    if (license.get(current.getValue('license'))) {

        var expiryDate = new GlideDateTime(
            license.getValue('expiry_date')
        );

        var today = new GlideDateTime();

        var difference = GlideDateTime.subtract(
            today,
            expiryDate
        );

        var daysToExpiry = Math.floor(
            difference.getNumericValue() / 86400000
        );

        current.setValue(
            'days_to_expiry',
            daysToExpiry
        );
    }


    // Update review details
    current.setValue(
        'review_date',
        new GlideDate()
    );

    current.setValue(
        'review_status',
        'analysis_completed'
    );
    if (result.recommendation == 'do_not_renew') {

        gs.eventQueue(
            'x_1904737_smart_0.high_waste_license',
            current,
            current.getValue('license'),
            current.getValue('assignment')
        );

    }

})(current, previous);
